import { useCallback, useEffect, useRef } from "react";
import { ACTIVE_RUN_STATE_EVENT, getActiveRun, } from "../active-run-state.js";
import { trackAgentChatLifecycle } from "../analytics.js";
export function useAgentChatLifecycleTracking({ surface, threadId, tabId, onActiveRunChange, }) {
    const activeRef = useRef(null);
    const observedRunIdRef = useRef(null);
    useEffect(() => {
        trackAgentChatLifecycle({
            phase: "surface-mounted",
            surface,
            ...(threadId ? { threadId } : {}),
            ...(tabId ? { tabId } : {}),
        });
    }, [surface, tabId, threadId]);
    useEffect(() => {
        const sync = (state = getActiveRun()) => {
            const active = Boolean(threadId && state?.threadId === threadId && state.runId);
            if (activeRef.current !== active) {
                activeRef.current = active;
                onActiveRunChange?.(active);
            }
            if (!active || !state)
                return;
            if (observedRunIdRef.current === state.runId)
                return;
            observedRunIdRef.current = state.runId;
            trackAgentChatLifecycle({
                phase: "run-observed",
                surface,
                threadId: state.threadId,
                runId: state.runId,
                ...(tabId ? { tabId } : {}),
            });
        };
        sync();
        const activeRunHandler = (event) => {
            const state = event
                .detail?.state;
            sync(state ?? null);
        };
        const storageHandler = () => sync();
        window.addEventListener(ACTIVE_RUN_STATE_EVENT, activeRunHandler);
        window.addEventListener("storage", storageHandler);
        return () => {
            window.removeEventListener(ACTIVE_RUN_STATE_EVENT, activeRunHandler);
            window.removeEventListener("storage", storageHandler);
        };
    }, [onActiveRunChange, surface, tabId, threadId]);
    return useCallback((runId) => {
        trackAgentChatLifecycle({
            phase: "run-stopped",
            surface,
            ...(threadId ? { threadId } : {}),
            ...(runId ? { runId } : {}),
            ...(tabId ? { tabId } : {}),
        });
    }, [surface, tabId, threadId]);
}
